    /** Дополняет продукт микронутриентами по имени (если есть в карте). */
    fun enrich(p: ProductEntity): ProductEntity {
        val a = map[p.name] ?: return p
        return p.copy(
            vitA = a[0], vitC = a[1], vitD = a[2], vitE = a[3], vitK = a[4],
            vitB6 = a[5], vitB12 = a[6], folate = a[7], calcium = a[8], iron = a[9],
            magnesium = a[10], zinc = a[11], potassium = a[12], sodium = a[13], selenium = a[14]
        )
    }
